class OneShotHttpServer {
 public:
  explicit OneShotHttpServer(std::string body) : m_body(std::move(body)) {
    m_listenFd = socket(AF_INET, SOCK_STREAM, 0);
    sockaddr_in addr{};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = 0;
    socklen_t len = sizeof(addr);
    if (m_listenFd < 0 ||
        bind(m_listenFd, reinterpret_cast<sockaddr *>(&addr), len) != 0 ||
        listen(m_listenFd, 1) != 0 ||
        getsockname(m_listenFd, reinterpret_cast<sockaddr *>(&addr), &len) !=
            0) {
      if (m_listenFd >= 0) {
        close(m_listenFd);
      }
      throw std::runtime_error("OneShotHttpServer: cannot listen");
    }
    m_port = ntohs(addr.sin_port);
    m_thread = std::thread([this] { serve(); });
  }

  ~OneShotHttpServer() {
    m_thread.join();
    close(m_listenFd);
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @return The URL of the endpoint, with the default CREST API path
  ////////////////////////////////////////////////////////////////////////////////
  std::string url() const {
    return "http://127.0.0.1:" + std::to_string(m_port) + "/api-v6.0";
  }

 private:
  static constexpr int kAcceptTimeoutMs = 10000;

  void serve() {
    // Bounded wait, so the destructor's join can't hang when no request comes.
    pollfd listener{m_listenFd, POLLIN, 0};
    if (poll(&listener, 1, kAcceptTimeoutMs) <= 0) {
      return;
    }
    const int fd = accept(m_listenFd, nullptr, nullptr);
    if (fd < 0) {
      return;
    }
    std::string request;
    char buf[4096];
    std::size_t headerEnd = std::string::npos;
    while (headerEnd == std::string::npos) {
      const ssize_t n = recv(fd, buf, sizeof(buf), 0);
      if (n <= 0) {
        close(fd);
        return;
      }
      request.append(buf, n);
      headerEnd = request.find("\r\n\r\n");
    }
    std::string headers = request.substr(0, headerEnd);
    std::transform(headers.begin(), headers.end(), headers.begin(),
                   [](unsigned char c) { return std::tolower(c); });
    if (headers.find("expect: 100-continue") != std::string::npos) {
      const std::string cont = "HTTP/1.1 100 Continue\r\n\r\n";
      send(fd, cont.data(), cont.size(), 0);
    }
    // Drain the body so curl finishes sending before the reply arrives.
    const std::size_t lengthPos = headers.find("content-length:");
    if (lengthPos != std::string::npos) {
      const std::size_t bodyLength = std::stoul(headers.substr(lengthPos + 15));
      std::size_t received = request.size() - headerEnd - 4;
      while (received < bodyLength) {
        const ssize_t n = recv(fd, buf, sizeof(buf), 0);
        if (n <= 0) {
          break;
        }
        received += n;
      }
    }
    const std::string reply =
        "HTTP/1.1 201 Created\r\nContent-Type: application/json\r\n"
        "Content-Length: " +
        std::to_string(m_body.size()) + "\r\nConnection: close\r\n\r\n" +
        m_body;
    send(fd, reply.data(), reply.size(), 0);
    close(fd);
  }

  std::string m_body;
  int m_listenFd = -1;
  int m_port = 0;
  std::thread m_thread;
}

