class PayloadFileDir {
 public:
  PayloadFileDir() : m_dir(uniqueTagName("/tmp/crest_store_data_files")) {
    std::filesystem::create_directories(m_dir);
  }

  ~PayloadFileDir() {
    for (const auto &path : m_paths) {
      std::filesystem::remove(path);
    }
    std::filesystem::remove(m_dir);
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Write content to a new file in the directory
  /// @return The file's storeData reference, file://<path>
  ////////////////////////////////////////////////////////////////////////////////
  std::string write(const std::string &name, const std::string &content) {
    const std::string path = m_dir + "/" + name;
    std::ofstream(path) << content;
    m_paths.push_back(path);
    return "file://" + path;
  }

 private:
  std::string m_dir;
  std::vector<std::string> m_paths;
}

PayloadFileDir() : m_dir(uniqueTagName("/tmp/crest_store_data_files")) {
