class StoreDataHashesTest : public MultiClientTestFixture {
 protected:
  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Create a tag whose end of validity is kInitialEndOfValidity
  /// @return The tag name
  ////////////////////////////////////////////////////////////////////////////////
  std::string createTag() {
    const std::string tagName = uniqueTagName("store_data_hashes");
    TagDto tag(tagName, "time", "storeData hash test tag");
    // Oracle-backed servers reject an empty payloadSpec (stored as NULL).
    tag.setObjectType("JSON");
    tag.setEndOfValidity(kInitialEndOfValidity);
    myCrestApi->createTag(tag);
    return tagName;
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @return The payload hash of each of the tag's IOVs, by since
  ////////////////////////////////////////////////////////////////////////////////
  std::map<uint64_t, std::string> storedHashes(const std::string &tagName) {
    const IovSetDto iovs =
        myCrestApi->selectIovs(tagName, 0, -1, 0, 1000, 0, "id.since:ASC");
    std::map<uint64_t, std::string> hashes;
    for (const auto &iov : iovs.getResources()) {
      hashes[iov.getSince()] = iov.getPayloadHash();
    }
    return hashes;
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Assert that stored holds input's since values in input order, and
  ///         that each hash is the one the tag reports for that since
  ////////////////////////////////////////////////////////////////////////////////
  void expectStoredPairs(const std::string &tagName, const StoreSetDto &input,
                         const StoreSetDto &stored) {
    ASSERT_EQ(stored.size(), input.size());
    const auto hashes = storedHashes(tagName);
    ASSERT_EQ(hashes.size(), input.size());
    for (std::size_t i = 0; i < input.size(); ++i) {
      const StoreDto &dto = stored.getResources()[i];
      EXPECT_EQ(dto.getSince(), input.getResources()[i].getSince());
      EXPECT_EQ(dto.getHash().size(), 64u);
      EXPECT_EQ(dto.getHash(), hashes.at(dto.getSince()));
      EXPECT_TRUE(dto.getData().empty());
    }
  }

  ////////////////////////////////////////////////////////////////////////////////
  /// @brief  Store one JSON payload through the derived type, whose
  ///         storeData declares the default endTime
  ////////////////////////////////////////////////////////////////////////////////
  void storeWithDefaultEndTime(const std::string &tagName) {
    StoreSetDto input;
    input.push_back(StoreDto(100, "", "default endTime payload"));
    if (storage == "CrestServer") {
      dynamic_cast<CrestApi &>(*myCrestApi).storeData(tagName, input);
    } else {
      dynamic_cast<CrestApiFs &>(*myCrestApi).storeData(tagName, input);
    }
  }
}

