TEST_P(StoreDataHashesTest, JsonReturnsHashesInInputOrder) {
  const std::string tagName = createTag();
  // Not sorted by since, so input order and since order differ.
  StoreSetDto input;
  input.push_back(StoreDto(3000, "", "json payload at 3000"));
  input.push_back(StoreDto(1000, "", "json payload at 1000"));
  input.push_back(StoreDto(2000, "", "json payload at 2000"));

  const StoreSetDto stored =
      myCrestApi->storeData(tagName, input, "JSON", "test", "none", "1", 0);

  expectStoredPairs(tagName, input, stored);
}

TEST_P(StoreDataHashesTest, FileReturnsHashesInInputOrder) {
  const std::string tagName = createTag();
  PayloadFileDir files;
  StoreSetDto input;
  input.push_back(StoreDto(3000, "", files.write("p3000.txt", "file 3000")));
  input.push_back(StoreDto(1000, "", files.write("p1000.txt", "file 1000")));
  input.push_back(StoreDto(2000, "", files.write("p2000.txt", "file 2000")));

  const StoreSetDto stored =
      myCrestApi->storeData(tagName, input, "FILE", "test", "none", "1", 0);

  expectStoredPairs(tagName, input, stored);
  EXPECT_EQ(stored.getResources()[0].getHash(),
            CrestApiBase::getHash("file 3000"));
}

TEST_P(StoreDataHashesTest, StaticGetHashMatchesStoredHash) {
  const std::string tagName = createTag();
  const std::string data = "payload hashed without a client";
  StoreSetDto input;
  input.push_back(StoreDto(500, "", data));

  const StoreSetDto stored =
      myCrestApi->storeData(tagName, input, "JSON", "test", "none", "1", 0);

  const std::string hash = Crest::CrestApiBase::getHash(data);
  EXPECT_EQ(hash, stored.getResources()[0].getHash());
  EXPECT_EQ(hash, storedHashes(tagName).at(500));
}

TEST_P(StoreDataHashesTest, DefaultEndTimeOnServerResetsEndOfValidity) {
  if (storage != "CrestServer") {
    GTEST_SKIP() << "the file storage ignores endTime";
  }
  const std::string tagName = createTag();
  ASSERT_EQ(myCrestApi->findTag(tagName).getEndOfValidity(),
            kInitialEndOfValidity);

  storeWithDefaultEndTime(tagName);

  EXPECT_EQ(myCrestApi->findTag(tagName).getEndOfValidity(), 0u);
}

TEST_P(StoreDataHashesTest, ExplicitEndTimeOnServerSetsEndOfValidity) {
  if (storage != "CrestServer") {
    GTEST_SKIP() << "the file storage ignores endTime";
  }
  const std::string tagName = createTag();
  StoreSetDto input;
  input.push_back(StoreDto(100, "", "explicit endTime payload"));

  myCrestApi->storeData(tagName, input, "JSON", "test", "none", "1", 12345);

  EXPECT_EQ(myCrestApi->findTag(tagName).getEndOfValidity(), 12345u);
}

TEST_P(StoreDataHashesTest, FileStorageKeepsEndOfValidity) {
  if (storage != "CrestFilesystem") {
    GTEST_SKIP() << "the server writes endTime as the end of validity";
  }
  const std::string tagName = createTag();

  storeWithDefaultEndTime(tagName);
  StoreSetDto input;
  input.push_back(StoreDto(200, "", "explicit endTime payload"));
  myCrestApi->storeData(tagName, input, "JSON", "test", "none", "1", 12345);

  EXPECT_EQ(myCrestApi->findTag(tagName).getEndOfValidity(),
            kInitialEndOfValidity);
}

TEST(StoreDataHashesServerResponseTest, FileResponseCountMismatchThrows) {
  OneShotHttpServer server(
      R"({"format":"StoreSetDto","size":1,"datatype":"payloads",)"
      R"("resources":[{"since":1000,"hash":"abc","data":"x",)"
      R"("streamerInfo":"none"}]})");
  CrestApi api(server.url());
  PayloadFileDir files;
  StoreSetDto input;
  input.push_back(StoreDto(1000, "", files.write("a.txt", "a")));
  input.push_back(StoreDto(2000, "", files.write("b.txt", "b")));

  try {
    api.storeData("any_tag", input, "FILE", "test", "none", "1", 0);
    FAIL() << "storeData accepted a response with too few IOVs";
  } catch (const CrestException &e) {
    EXPECT_NE(std::string(e.what()).find("returned 1 stored IOVs for 2 sent"),
              std::string::npos)
        << e.what();
  }
